{"implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    core = payload['core_distance']
    distances = payload['distances']
    for n in nodes:
        if n not in core:
            raise ValueError(f"Missing core distance for {n}")
    edges = []
    for d in distances:
        u, v, w = d
        if u not in core or v not in core:
            raise ValueError("Unknown node in distance")
        if u > v:
            u, v = v, u
        mut = max(core[u], core[v], w)
        edges.append((u, v, mut))
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Disconnected graph")
    return {"edges": mst_edges, "total_weight": total_weight}
"}
